"""Compile the documented research corpus. No application or demonstration data."""
from pathlib import Path
import json, csv, re, hashlib

ROOT = Path(__file__).resolve().parents[1]
CACHE = Path('/workspace/eia-evidence')
entities, claims, edges, timeline = [], [], [], []

def entity(id, name, kind, summary, body, sources, **extra):
    entities.append(dict(id=id,name=name,kind=kind,summary=summary,body=body,sources=sources,country=extra.pop('country','Россия'),**extra))

def claim(id,title,body,sources,objects,grade='C',topic='Корпоративная сеть',date='',nature='Вторичные данные',quote='',location=''):
    claims.append(dict(id=id,title=title,body=body,sources=sources,objects=objects,grade=grade,topic=topic,date=date,nature=nature,quote=quote,location=location))

def edge(a,b,relation,source,grade='C',period='',kind='деловая',significance='',end=''):
    edges.append(dict(id=f'e{len(edges)+1:03}',source=a,target=b,relation=relation,sources=source if isinstance(source,list) else [source],grade=grade,period=period,end=end,kind=kind,significance=significance or 'Отдельное документированное отношение; цепочка не означает контроль её конечного участника.'))

def event(date,title,body,objects,sources,grade='C'):
    timeline.append(dict(date=date,title=title,body=body,objects=objects,sources=sources,grade=grade))

