extra_people = [
 ('peshev','Илья Николаевич Пешев','Совладелец «Мясного клуба» и руководитель ООО «Шёлковый путь».','По корпоративным карточкам имеет 50% «Мясного клуба» и является учредителем/директором «Шёлкового пути», зарегистрированного 26.05.2026. Историческое ИП по перевозкам с 18.02.2022 отмечено прекращённым. Договоров с EIA и личных связей с её советом не установлено.',['e4ec549205cf','93a81c6c66d5','f81d3a3a58cb']),
 ('kritskaya','Светлана Владимировна Крицкая','Директор «Мясного клуба» с 17.11.2023 по корпоративным карточкам.','Доля в капитале в просмотренной карточке не указана. Рабочую роль нельзя превращать в участие в EIA или родство с людьми, имеющими похожие фамилии.',['9354b286288d','93a81c6c66d5']),
 ('bogdanchikova','Ирина Валериевна Богданчикова','Историческая совладелица двух компаний Скаредновой.','В «Бренд девелопмент групп» указано 20%, в «Главтехэкспертизе» — 50%. Обе компании ликвидированы в 2019 году. Общая собственность в прошлом не доказывает текущий деловой альянс или участие в EIA.',['3fd66db31582','b1f7ea2af630']),
 ('makoveev','Алексей Васильевич Маковеев','Исторический владелец 60% «Бренд девелопмент групп».','В карточке указан с 07.02.2011. Другие биографические и корпоративные совпадения не исследованы; влияние на EIA не установлено.',['3fd66db31582']),
 ('belyaninov','Андрей Юрьевич Бельянинов','Генеральный секретарь Ассамблеи по её официальному сайту.','EIA называет его подписантом соглашения 18.09.2026. Сайт Ассамблеи упоминает членство в государственной комиссии РФ по делам ЮНЕСКО. Независимый государственный акт о текущем составе комиссии в корпус не получен. Это не доказательство межправительственного статуса Ассамблеи, личного финансирования EIA или контроля ЮНЕСКО над агентством.',['22ecc6ec867c','0abb724da346','1e6cc5cf7ac3']),
 ('smirnova','Светлана Константиновна Смирнова','Председатель генерального совета Ассамблеи по её сайту.','Также названа первым заместителем генсекретаря, членом Совета при Президенте РФ по межнациональным отношениям и председателем «Сенежского форума». Это институциональные самоописания источника; государственные назначения отдельно не проверены. В журнале «Народная дипломатия» опубликовано её обращение. Доля или финансирование EIA не установлены.',['22ecc6ec867c','cb2ae9ba64bc']),
 ('barkov','Леонид Барков','Главный редактор «Народной дипломатии» №4 и «Первого» №1 по PDF.','В Federation №8 указан среди авторов. В №3 «Народной дипломатии» главным редактором назван Рабинович, а в №4 — Барков. Основание и точная дата перехода полномочий не опубликованы. Другие однофамильцы не отождествлялись.',['de8edd89579b','cb2ae9ba64bc','146fc984a824','1e6cc5cf7ac3']),
 ('marianna','Марианна Палагутина','Помощник главного редактора в нескольких PDF.','В №3 «Народной дипломатии» указано написание «Палагутина (Крицкая)». Достаточных данных для связи со Светланой Крицкой, определения родства или собственности нет. В исследовании сохранена только опубликованная редакционная роль.',['146fc984a824','cb2ae9ba64bc','1e6cc5cf7ac3']),
 ('hashchansky','Хащанский В. В.','Учредитель Federation в выходных данных №8.','Полное имя и корпоративные идентификаторы не установлены. Он не объявлен владельцем EIA: речь идёт о конкретном издании и конкретном выпуске.',['de8edd89579b']),
 ('leonov','Евгений Леонов','Генеральный директор «Уникальных ландшафтов» по сайту журнала.','В PDF научного журнала указан как Евгений Леонидович Леонов, соавтор статьи и руководитель АНО. Договор издательских услуг с EIA и финансовые обязательства не опубликованы в полученном корпусе.',['d569bfee0c8f','a2147574ceaf']),
 ('vagizov','Марсель Равильевич Вагизов','Главный редактор «Геоинформационного моделирования».','PDF указывает степень доктора технических наук, доцента; статья представляет его проректором РГГМУ по ИТ и цифровой трансформации. Это опубликованная профессиональная аффилиация, а не участие в капитале EIA.',['d569bfee0c8f','a2147574ceaf']),
 ('milovanova','Ольга Милованова','Руководитель комитета по импакт-компаниям по новости EIA.','Публикация 30.09.2026 заявляет назначение в совете «Инвестиции и трансфер технологий» АНМ. Приказ о назначении, юридическая структура комитета, список проектов и суммы инвестиций не получены. Назначение не трактуется как установленный финансовый поток.',['3f0044b60199']),
 ('tulin','Наталья Викторовна Тулин','Историческая участница ООО «АН 1965».','В карточке указана доля 33,33% с 18.04.2012. Компания ликвидирована в 2018 году, текущая связь с EIA не установлена.',['c05e05af70df']),
 ('ivanova','Елена Евгеньева Иванова','Историческая участница ООО «АН 1965».','В карточке указана доля 33,33% с 14.10.2011. ФИО воспроизведено в написании источника. Компания ликвидирована, связь с EIA не установлена.',['c05e05af70df']),
]
